mapper.update:
UPDATE orders
SET payable_amount = (
    SELECT COALESCE(SUM((order_items.unit_price + order_items.options_amount) *
        (order_items.quantity - COALESCE(approved_cancellations.cancelledQuantity, 0))), 0)
    FROM order_items
    LEFT JOIN (
        SELECT order_item_id, SUM(requested_quantity) AS cancelledQuantity
        FROM order_item_cancellation_requests
        WHERE status = 'APPROVED'
        GROUP BY order_item_id
    ) approved_cancellations ON approved_cancellations.order_item_id = order_items.id
    WHERE order_items.order_id = #{orderId}
) WHERE id = #{orderId}
